import{_ as e,o,c as p,a3 as r}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"1.6智能最大毛产","description":"","frontmatter":{"translationSource":{"title":"1.6智能最大毛产","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}]]},"headers":[],"relativePath":"zh/full-storage-oscillation-plan.md","filePath":"zh/page-JEibHxjUhjwaznRy5jp6oc.md"}'),s={name:"zh/full-storage-oscillation-plan.md"};function i(l,a,t,n,c,h){return o(),p("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><h1 id="_1-6智能最大毛产" tabindex="-1">1.6智能最大毛产 <a class="header-anchor" href="#_1-6智能最大毛产" aria-label="Permalink to &quot;1\\.6智能最大毛产&quot;">​</a></h1><blockquote><p>源页面 ID：<code>JEibHxjUhjwaznRy5jp6oc</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span class="mark-red"><strong>#言：我息壤模块呢？</strong></span></p><p>需求：</p><p>景玉谷12双口息壤，自启动12双口9准入口方案已做好，赤石点：设备数爆炸</p><p>其他部分：</p><p>应龙关去掉息壤加压，自连暗管外置，加东西（分离芯）</p><p>主基地待压缩（精炼炉，污水处理垃圾桶，壤晶线，炼铁磨粉分离芯，半速电池/，息壤震荡/，息壤液气转化/，息壤总线/，重息壤/）</p><p><span id="source-block-wt8iPy0gMDFywV7KEmhkoR"></span></p><h2 id="视频文案" tabindex="-1">视频文案 <a class="header-anchor" href="#视频文案" aria-label="Permalink to &quot;视频文案&quot;">​</a></h2><p><span id="source-block-YS3tBMxxg8McQAfMF35GpN"></span></p><h3 id="产线展示" tabindex="-1">产线展示 <a class="header-anchor" href="#产线展示" aria-label="Permalink to &quot;产线展示&quot;">​</a></h3><p>这一代对上一代的超越</p><p>更详细的功能介绍，尤其是插件演示</p><p>对观众的期许：比如说在评论区留下正面言论、希望答疑主要前往答疑网站和群聊并表达我们缺乏一一回复能力、注意到评论区甚至群内群友有很多并不正确的回复先肯定精神再指出错误的回复会造成困扰最后并不一棒子打死而是进一步建议有问题多去群/答疑网站并以答疑人员回答为准——虽然答疑人员不一定绝对正确但是不可否认的是他们比多数人更加熟悉产线并随时可以转接开发人员</p><p><span id="source-block-UU4P5kkrLs4f54xy23COub"></span></p><h3 id="产线讲解" tabindex="-1">产线讲解 <a class="header-anchor" href="#产线讲解" aria-label="Permalink to &quot;产线讲解&quot;">​</a></h3><p>模块简述</p><p>自动配平路径讲解</p><p><span id="source-block-VjRatZPY7VytfwEPSU53Zl"></span></p><h3 id="安装教程" tabindex="-1">安装教程 <a class="header-anchor" href="#安装教程" aria-label="Permalink to &quot;安装教程&quot;">​</a></h3><p><span id="source-block-0rfOwq29K0j4iJLxK2zROW"></span></p><h2 id="产线布局" tabindex="-1">产线布局 <a class="header-anchor" href="#产线布局" aria-label="Permalink to &quot;产线布局&quot;">​</a></h2><p><span id="source-block-pZevVPXGlCFmWxYpA22zV7"></span></p><h3 id="景玉谷" tabindex="-1">景玉谷 <a class="header-anchor" href="#景玉谷" aria-label="Permalink to &quot;景玉谷&quot;">​</a></h3><p><strong>目前主要制约：设备数量</strong></p><p>12双口息壤（必要）</p><p>2分离芯（必要）</p><p>3双带赤铜精炼（必要）</p><p>种植组芽针锦草各一带打粉（必要）</p><p>蓝铁精炼溢流打粉</p><p>零件机3灼1赫1蓝铁</p><p>灼铜装备元件机</p><p>中电（可选）（可以是砂叶也可以是封装）</p><p><span id="source-block-tkw1iLW0nUBPYwoeRyJccp"></span></p><h3 id="主基地" tabindex="-1">主基地 <a class="header-anchor" href="#主基地" aria-label="Permalink to &quot;主基地&quot;">​</a></h3><p>息壤液震荡（4池</p><p>固定2池，兼容</p><p>抗一切壤晶</p><p>赤铜精炼溢流打粉12</p><p>赤铜精炼双带2耦合垃圾桶</p><p>蓝铁块和蓝铁零件为起点的小药产线</p><p>中电</p><p><span id="source-block-krXKbnL5O0kAIMgiAR5mXr"></span></p><h3 id="应龙关" tabindex="-1">应龙关 <a class="header-anchor" href="#应龙关" aria-label="Permalink to &quot;应龙关&quot;">​</a></h3><p>暗管外置——固气机改溢流、分离芯</p><p><span id="source-block-wtaH6muc44xSRMXmWrcqDs"></span></p><h3 id="首墩" tabindex="-1">首墩 <a class="header-anchor" href="#首墩" aria-label="Permalink to &quot;首墩&quot;">​</a></h3><p><span id="source-block-6SkebfDdeH1om407PRb3Pg"></span></p><h5 id="日用品插件" tabindex="-1">日用品插件 <a class="header-anchor" href="#日用品插件" aria-label="Permalink to &quot;日用品插件&quot;">​</a></h5><p><span id="source-block-0kspTcZc9FCeTSNB1Zsg97"></span></p><h5 id="紫药、息壤液罐装、重息壤液罐装、赤铜零件、小电、待补充" tabindex="-1">紫药、息壤液罐装、重息壤液罐装、赤铜零件、小电、待补充 <a class="header-anchor" href="#紫药、息壤液罐装、重息壤液罐装、赤铜零件、小电、待补充" aria-label="Permalink to &quot;紫药、息壤液罐装、重息壤液罐装、赤铜零件、小电、待补充&quot;">​</a></h5><p><span id="source-block-5Fcbr8mwQYsbQVWw3qnHU8"></span></p><h5 id="缘缘庄插件" tabindex="-1">缘缘庄插件 <a class="header-anchor" href="#缘缘庄插件" aria-label="Permalink to &quot;缘缘庄插件&quot;">​</a></h5><p><span id="source-block-FBtPNvsLFil3Wtwnz99gI5"></span></p><h2 id="散装模块" tabindex="-1">散装模块 <a class="header-anchor" href="#散装模块" aria-label="Permalink to &quot;散装模块&quot;">​</a></h2><p><span id="source-block-Z5vNKLZ8EC4EtG1KTC6C8F"></span></p><h3 id="壤晶线" tabindex="-1">壤晶线 <a class="header-anchor" href="#壤晶线" aria-label="Permalink to &quot;壤晶线&quot;">​</a></h3><p>《明日方舟：终末地》蓝图 [单边抗一切壤晶]分享码EF01u28U5Ie870a7AoOU 请复制后前往游戏中使用。</p><p><span id="source-block-HUOTrAo1XGkxDqwoWUNxYD"></span></p><h3 id="重息壤" tabindex="-1">重息壤 <a class="header-anchor" href="#重息壤" aria-label="Permalink to &quot;重息壤&quot;">​</a></h3><p>《明日方舟：终末地》蓝图 [四核重息壤]分享码EF01I43EaUUUu9o45o08 请复制后前往游戏中使用。</p><p><span id="source-block-A8b2BmNv3r8OczTH6mi4LB"></span></p><h3 id="铜处理" tabindex="-1">铜处理 <a class="header-anchor" href="#铜处理" aria-label="Permalink to &quot;铜处理&quot;">​</a></h3><p>《明日方舟：终末地》蓝图 [临时精炼]分享码EF013Eo56eee8a510579 请复制后前往游戏中使用。<br> 《明日方舟：终末地》蓝图 [分离芯]分享码EF01U9ea48887OiI7Oa8 请复制后前往游戏中使用。</p><p><span id="source-block-h3O6ZElo5DYvpwQqWExr9k"></span></p><h3 id="蓝铁处理" tabindex="-1">蓝铁处理 <a class="header-anchor" href="#蓝铁处理" aria-label="Permalink to &quot;蓝铁处理&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abd42c7b4bee2263.q90-fcf8ba08a760fb80.webp" alt="16智能最大毛产"></p><div class="logistics-image-caption" data-source-block="K6uojhba5PhZY4h7JS1DHr"><p>赫塔-蓝铁精炼及打粉</p></div><p><span id="source-block-V6Z6WWObS8Sp9VROKaVcgK"></span></p><h3 id="息壤" tabindex="-1">息壤 <a class="header-anchor" href="#息壤" aria-label="Permalink to &quot;息壤&quot;">​</a></h3><p><span class="mark-red">东西呢快点端上来！！！</span></p><p><span id="source-block-PSVH9EWPl3In6oiZbgmPV9"></span></p><h3 id="息壤液满仓震荡模块" tabindex="-1">息壤液满仓震荡模块 <a class="header-anchor" href="#息壤液满仓震荡模块" aria-label="Permalink to &quot;息壤液满仓震荡模块&quot;">​</a></h3><p><span id="source-block-qFVfEvK9jO1NhKefnV1XSG"></span></p><h4 id="控息壤" tabindex="-1">控息壤 <a class="header-anchor" href="#控息壤" aria-label="Permalink to &quot;控息壤&quot;">​</a></h4><p><span id="source-block-GiL6uZNnTppYmPRchrcBmr"></span></p><h4 id="控水" tabindex="-1">控水 <a class="header-anchor" href="#控水" aria-label="Permalink to &quot;控水&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7c56052227e27422.q90-4b211e99002b0a11.webp" alt="16智能最大毛产"></p><p>填充物：除了最左断电箱都填充250锦草、断电池填充4杂物和传送带长的锦草种子</p><p>应该是省了非常多设备数了，代价仅是4管道件。不过我还没压缩（（</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-280aed2b84bcdf55.png" alt="16智能最大毛产"></p><div class="logistics-image-caption" data-source-block="cXD5Oa5klddFZoIT9qBbsU"><p>优先级如图所示</p></div><p>初步压缩完成；断电池制备较久，不知道要不要优化</p><p><s>《明日方舟：终末地》蓝图 [武陵断电池]分享码EF015i2eii8O2uaa0eIoe 请复制后前往游戏中使用。</s></p><p><s>《明日方舟：终末地》蓝图 [震荡息壤液]分享码EF01E75U77u25o56E3uIa 请复制后前往游戏中使用。</s></p><p><strong>已被君大人优化</strong></p></div>',1)])])}const u=e(s,[["render",i]]);export{b as __pageData,u as default};
